import sys

def main():
    input = sys.stdin.readline
    n, k = map(int, input().split())
    v = list(map(int, input().split()))
    t = input().strip()

    # 极性系数 p_i
    p = [1 if ch == '1' else -1 for ch in t]

    # 基础效用 base = sum(p_i * (v_i + 1))
    base = sum(p[i] * (v[i] + 1) for i in range(n))

    # 后缀和 suf[i] = sum_{j=i}^{n-1} p_j
    suf = [0] * n
    suf[-1] = p[-1]
    for i in range(n - 2, -1, -1):
        suf[i] = suf[i + 1] + p[i]

    # 收集正贡献切割点
    contributions = []
    for i in range(n - 1):
        if suf[i + 1] > 0:
            contributions.append(suf[i + 1])

    # 选取最多 k-1 个最大正贡献
    contributions.sort(reverse=True)
    extra = sum(contributions[:max(0, k - 1)])

    print(base + extra)

if __name__ == "__main__":
    main()
```

